export function swing(
  out: Vec3,
  a: Formation,
  b: Formation,
  t: number,
  dwell: number,
): Vec3 {
  for (let k = 0; k < 3; k++) {
    out[k] = lerp(a.sway[k] * (dwell - 0.5), b.sway[k] * -0.5, t);
